import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Vorausgefüllte Links","description":"Formularlinks mit bereits eingetragenen Werten erzeugen und einsetzen.","frontmatter":{"title":"Vorausgefüllte Links","description":"Formularlinks mit bereits eingetragenen Werten erzeugen und einsetzen."},"headers":[],"relativePath":"formulare/vorausgefuellte-links.md","filePath":"formulare/vorausgefuellte-links.md","lastUpdated":1786086822000}'),a={name:"formulare/vorausgefuellte-links.md"};function s(l,e,o,u,d,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="vorausgefullte-links" tabindex="-1">Vorausgefüllte Links <a class="header-anchor" href="#vorausgefullte-links" aria-label="Permalink to &quot;Vorausgefüllte Links&quot;">​</a></h1><p>Ein <strong>vorausgefüllter Link</strong> öffnet ein Formular, in dem bestimmte Felder bereits befüllt sind. Ausfüllende müssen weniger eingeben — und Sie wissen mehr über den Kontext.</p><h2 id="link-erzeugen" tabindex="-1">Link erzeugen <a class="header-anchor" href="#link-erzeugen" aria-label="Permalink to &quot;Link erzeugen&quot;">​</a></h2><p>Im Freigabedialog eines Formulars: <strong>Formular vorausgefüllt teilen</strong>.</p><p>Es öffnet sich ein Editor mit dem Formular selbst:</p><blockquote><p><em>Erstellen Sie einen Link, um dieses Formular vorab auszufüllen.</em></p><p><em>Geben Sie bitte die Daten in die entsprechenden Formularfelder ein. Kopieren Sie den generierten Link und nutzen Sie ihn, um das Formular mit den vorausgefüllten Daten schnell und einfach zu teilen.</em></p></blockquote><p>Sie füllen also einfach das Formular so aus, wie es Empfänger vorfinden sollen, und kopieren den erzeugten Link.</p><h2 id="typische-anwendungen" tabindex="-1">Typische Anwendungen <a class="header-anchor" href="#typische-anwendungen" aria-label="Permalink to &quot;Typische Anwendungen&quot;">​</a></h2><h3 id="herkunft-mitschreiben" tabindex="-1">Herkunft mitschreiben <a class="header-anchor" href="#herkunft-mitschreiben" aria-label="Permalink to &quot;Herkunft mitschreiben&quot;">​</a></h3><p>Legen Sie im Grid ein Feld <code>Quelle</code> an, setzen Sie es im Formular auf <strong>Nicht sichtbar</strong>, und erzeugen Sie je Kanal einen Link mit unterschiedlichem Wert — <code>Newsletter</code>, <code>Website</code>, <code>Messe</code>.</p><p>Ausfüllende merken nichts davon. Sie sehen später in einer nach <code>Quelle</code> gruppierten Ansicht, welcher Kanal wie viel gebracht hat.</p><div class="tip custom-block"><p class="custom-block-title">Der häufigste Anwendungsfall</p><p>Diese Kombination aus verstecktem Feld und vorausgefülltem Link ist der Standardweg, um Kampagnen auseinanderzuhalten — ohne dass Ausfüllende etwas zusätzlich angeben müssen.</p></div><h3 id="wiederkehrende-angaben-vorbelegen" tabindex="-1">Wiederkehrende Angaben vorbelegen <a class="header-anchor" href="#wiederkehrende-angaben-vorbelegen" aria-label="Permalink to &quot;Wiederkehrende Angaben vorbelegen&quot;">​</a></h3><p>Standort, Abteilung, Veranstaltung, Ansprechpartner: alles, was für eine Gruppe von Ausfüllenden gleich ist. Setzen Sie die Felder zusätzlich auf <strong>Nicht änderbar</strong>, wenn der Wert feststehen soll.</p><h3 id="aus-einem-flow-heraus-verschicken" tabindex="-1">Aus einem Flow heraus verschicken <a class="header-anchor" href="#aus-einem-flow-heraus-verschicken" aria-label="Permalink to &quot;Aus einem Flow heraus verschicken&quot;">​</a></h3><p>Der Flow-Schritt <strong>Vorausgefüllter Formularlink</strong> erzeugt einen Link, der einen <strong>bestehenden</strong> Eintrag zur Bearbeitung öffnet.</p><p>Damit bauen Sie Rückmeldeschleifen: Der Flow schickt eine E-Mail mit dem Link, die Person ergänzt oder korrigiert etwas, und die Änderung landet direkt im vorhandenen Eintrag — ohne Doppeleintrag.</p><p>→ <a href="/docs/flows/aktionen">Aktionen</a></p><h3 id="einen-flow-mit-festen-werten-starten" tabindex="-1">Einen Flow mit festen Werten starten <a class="header-anchor" href="#einen-flow-mit-festen-werten-starten" aria-label="Permalink to &quot;Einen Flow mit festen Werten starten&quot;">​</a></h3><p>Kombiniert mit <strong>Automatisch absenden</strong> entsteht ein Link, der beim Öffnen sofort absendet und damit einen Flow startet. Als QR-Code auf einem Aushang genügt ein Scan.</p><div class="warning custom-block"><p class="custom-block-title">Auto-Absenden braucht vollständige Vorbelegung</p><p>Sendet sich das Formular selbst ab, hat niemand Gelegenheit, Pflichtfelder zu füllen. <strong>Alle</strong> benötigten Werte müssen über den Link oder über <em>Vorausgefüllt</em> gesetzt sein — sonst schlägt das Absenden fehl.</p></div><h2 id="auf-seiten" tabindex="-1">Auf Seiten <a class="header-anchor" href="#auf-seiten" aria-label="Permalink to &quot;Auf Seiten&quot;">​</a></h2><p>Auch Buttons auf einer <a href="/docs/seiten/was-sind-seiten">Seite</a> können ein Formular vorausgefüllt öffnen. Der Dialog dazu heißt <em>Formular vorausfüllen</em> — <em>Button konfigurieren, um Formulardaten vorauszufüllen.</em></p><h2 id="grenzen-und-vorsicht" tabindex="-1">Grenzen und Vorsicht <a class="header-anchor" href="#grenzen-und-vorsicht" aria-label="Permalink to &quot;Grenzen und Vorsicht&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Vorbelegte Werte stehen im Link</p><p>Die Werte sind Teil der Adresse und damit für jeden lesbar, der den Link hat — auch bei Feldern, die auf <em>Nicht sichtbar</em> stehen.</p><p>Legen Sie dort <strong>keine</strong> personenbezogenen oder vertraulichen Daten hinein. „Nicht sichtbar&quot; heißt nicht „geheim&quot;: Es blendet das Feld in der Oberfläche aus, mehr nicht.</p></div><div class="warning custom-block"><p class="custom-block-title">Feld gelöscht — Link unbrauchbar</p><p>Ein vorausgefüllter Link verweist auf konkrete Felder. Wird ein Feld gelöscht oder sein Typ geändert, greift die Vorbelegung nicht mehr. Prüfen Sie nach Strukturänderungen die im Umlauf befindlichen Links.</p></div><div class="tip custom-block"><p class="custom-block-title">Links benennen</p><p>Erzeugen Sie über <strong>Link hinzufügen</strong> je Kanal einen eigenen, benannten Link. So sehen Sie in der <a href="/docs/zusammenarbeit/externe-links">Links-Übersicht</a>, welcher Link wozu gehört, und können einzelne gezielt abschalten.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/formulare/formular-teilen">Formular teilen</a></li><li><a href="/docs/formulare/felder-konfigurieren">Felder konfigurieren</a></li><li><a href="/docs/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></li></ul>',29)])])}const g=n(a,[["render",s]]);export{m as __pageData,g as default};
